import java.util.NavigableMap;
import java.util.TreeMap;
import java.util.List;
import java.util.ArrayList;
import java.util.Random;
/**
 * Class responsible for handling the simulation of the disease.
 *
 * @version 1.0
 */
public class DiseaseHandler
{

    /*///////////////////////////////////////////////////////////////
                                 CONSTANTS
    //////////////////////////////////////////////////////////////*/

    // cooldown before the animal achieves natural immunity
    private static final int DISINFECTION_DURATION = 5;
    private final Random rand = Randomizer.getRandom();
    private final Field field;

    /*///////////////////////////////////////////////////////////////
                                   STATE
    //////////////////////////////////////////////////////////////*/

    private final NavigableMap<Integer, Integer> infectionCounts;
    private int currentStep;

    /*///////////////////////////////////////////////////////////////
                                CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    /**
     * Creates a new disease handler
     * @param field The field to later get the animals per block and compute the density
     */
    public DiseaseHandler(Field field)
    {
        this.field = field;
        infectionCounts = new TreeMap<>();
        reset();
    }

    /*///////////////////////////////////////////////////////////////
                          DISEASE SIMULATION LOGIC
    //////////////////////////////////////////////////////////////*/

    /**
     * Simulates the disease by iterating through every block in the field, and computing the density of the number of ppl infected 
     * in the given block to determine the likelyhood of being infected in the block
     */
    public void simulateDiseaseStep()
    {
        int infectionCount = 0;
        int[] totalInfections = {0};
        currentStep++;
        field.forEachAnimalBlock(block -> {
            int densityIndex = 0;
            List<Animal> uninfectedAnimals = new ArrayList<>();
            for(Animal animal : block) {
                if(animal.getInfectionTimestamp() != null && currentStep - animal.getInfectionTimestamp() < DISINFECTION_DURATION) {
                    // increase the counter of number of animals infected within this block.
                    densityIndex++;
                    continue;
                }
                if(animal.getInfectionTimestamp() == null) {
                    uninfectedAnimals.add(animal);
                }
            }
            // compute probability of being infected.
            double pValue = block.isEmpty() ? 0.0 : ((double) densityIndex / (double) block.size());
            for(Animal animal : uninfectedAnimals) {
                double randNumber = rand.nextDouble();
                if(randNumber < pValue ) {
                    animal.setInfectionTimestamp(currentStep);
                }
            }
            totalInfections[0] += densityIndex;
        });
        infectionCount = totalInfections[0];
        infectionCounts.put(currentStep, infectionCount);
    }

    /**
     * Reset the disease state for a fresh simulation run.
     */
    public void reset()
    {
        currentStep = 0;
        infectionCounts.clear();
    }

    /**
     * Returns the tracked infection counts over time.
     */
    public NavigableMap<Integer, Integer> getInfectionCounts()
    {
        return infectionCounts;
    }
}

import java.util.NavigableMap;
/**
 * A simple predator-prey simulator, based on a rectangular field
 * containing rabbits and foxes.
 *
 * @version 2.0
 */
public class Simulator
{

    /*///////////////////////////////////////////////////////////////
                                 CONSTANTS
    //////////////////////////////////////////////////////////////*/

    // The default dimensions
    private static final int DEFAULT_WIDTH = 120;
    private static final int DEFAULT_DEPTH = 80;

    /*///////////////////////////////////////////////////////////////
                                   STATE
    //////////////////////////////////////////////////////////////*/

    private final SimulationPopulation population;
    // The current state of the field.
    private final Field field;

    private final SimulatorClock clock;
    private final WeatherHandler weatherHandler;
    // The current step of the simulation.
    private int step;
    // A graphical view of the simulation.
    private final SimulatorView view;
    // handles the simulation of the disease
    private final DiseaseHandler diseaseHandler;
    // swing component dashboard
    private Dashboard dashboard;
    // generator for the initial terrain and population
    private final PopulationGenerator populationGenerator;

    /*///////////////////////////////////////////////////////////////
                                CONSTRUCTORS
    //////////////////////////////////////////////////////////////*/

    /**
     * Construct a simulation field with default size.
     */
    public Simulator() throws Exception
    {
        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
    }

    /**
     * Create a simulation field with the given size.
     * 
     * @param depth Depth of the field. Must be greater than zero.
     * @param width Width of the field. Must be greater than zero.
     */
    public Simulator(int depth, int width) throws Exception
    {
        if(depth % 20 != 0 || width % 20 != 0) {
            throw new Exception("Depth and Width must be factors of 20");
        }

        if(width <= 0 || depth <= 0) {
            depth = DEFAULT_DEPTH;
            width = DEFAULT_WIDTH;
        }

        population = new SimulationPopulation();
        field = new Field(depth, width);
        clock = new SimulatorClock();
        weatherHandler = new WeatherHandler(clock);
        diseaseHandler = new DiseaseHandler( field);
        // Create a view of the state of each location in the field.
        view = new SimulatorView(depth, width, this);
        populationGenerator = new PopulationGenerator(view, field);

        reset();
    }

    /**
     * Sets the dashboard field to later updates the interface at the end of simulation steps.
     * 
     * @param newDashboard the dashboard to be updated.
     */
    public void setDashboard(Dashboard newDashboard) {
        this.dashboard = newDashboard;
    }

    /*///////////////////////////////////////////////////////////////
                          ECOSYSTEM SIMULATION LOGIC
    //////////////////////////////////////////////////////////////*/

    /**
     * Run the simulation from its current state for a reasonably long period,
     * (1000 steps).
     */
    public void runLongSimulation()
    {
        simulate(1000);
    }

    /**
     * Run the simulation from its current state for the given number of steps.
     * Stop before the given number of steps if it ceases to be viable.
     * 
     * @param numSteps The number of steps to run for.
     */
    public void simulate(int numSteps)
    {
        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
            simulateOneStep();
        }
    }

    /**
     * Run the simulation from its current state for a single step.
     * Iterate over the whole field updating the state of each
     * fox and rabbit.
     */
    public void simulateOneStep()
    {
        step++;
        clock.incrementStep();
        weatherHandler.updateWeather();
        diseaseHandler.simulateDiseaseStep();
        population.simulateStep(weatherHandler.getWeather(), clock.getDayState());

        view.showStatus(step, field, clock, weatherHandler.getWeather());

        if(dashboard != null) {
            dashboard.updateDashboard();            
        }
    }

    /**
     * Reset the simulation to a starting position.
     */
    public void reset()
    {
        step = 0;
        clock.reset();
        weatherHandler.reset();
        diseaseHandler.reset();
        population.clear();
        populationGenerator.populate(population);

        // Show the starting state in the view.
        view.showStatus(step, field, clock, weatherHandler.getWeather());
    }

    /**
     * Returns the tracked disease history.
     */
    public NavigableMap<Integer, Integer> getDiseaseHistory()
    {
        return diseaseHandler.getInfectionCounts();
    }
}

import java.util.Random;
/**
 * A class responsible for generating the population,
 * as well as setting up the colours associated with each animal and plant class.
 *
 * @version 1.0
 */
public class PopulationGenerator
{

    /*///////////////////////////////////////////////////////////////
                                 CONSTANTS
    //////////////////////////////////////////////////////////////*/

    // A constant for initial number of infections in the generated population.
    private static final int INITIAL_INFECTION_COUNT = 11;
    private static final AnimalSpecies[] ANIMAL_SPAWN_ORDER = {
        AnimalSpecies.FOX,
        AnimalSpecies.REINDEER,
        AnimalSpecies.SHEEP,
        AnimalSpecies.BEAR,
        AnimalSpecies.WOLVERINE
    };
    private static final PlantSpecies[] PLANT_SPAWN_ORDER = {
        PlantSpecies.GRASS,
        PlantSpecies.SAGE,
        PlantSpecies.SEDGE
    };

    /*///////////////////////////////////////////////////////////////
                                   STATE
    //////////////////////////////////////////////////////////////*/

    private final SimulatorView view;
    private final AnimalFactory animalFactory;
    private final PlantFactory plantFactory;
    private final Field field;

    /*///////////////////////////////////////////////////////////////
                                CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    /**
     * Construct a population generator and set up the colours for representation of each animal class.
     */
    public PopulationGenerator(SimulatorView view, Field field)
    {
        this.view = view;
        this.field = field;
        animalFactory = new AnimalFactory(field);
        plantFactory = new PlantFactory(field);
        setUpColors();
    }

    /**
     * The RGB colours associated with the given animals and plants passed to the constructor of Color class from awt library.
     */
    private void setUpColors()
    {
        for (AnimalSpecies species : AnimalSpecies.values()) {
            view.setColor(species, species.getColor());
        }
        for (PlantSpecies species : PlantSpecies.values()) {
            view.setColor(species, species.getColor());
        }
        view.showColors();
    }

    /**
     * Populate the grid with animals and plants, infect the animals.
     * 
     * @param population The population to populate.
     */
    public void populate(SimulationPopulation population)
    {
        field.clear();
        populateAnimals(population);
        population.infectInitialAnimals(INITIAL_INFECTION_COUNT);
        populatePlants(population);
    }

    private void populateAnimals(SimulationPopulation population)
    {
        Random rand = Randomizer.getRandom();
        field.forEachLocation((row, col) -> {
            Location location = new Location(row, col);
            Animal animal = createAnimalAt(rand, location);
            if(animal != null) {
                population.addAnimal(animal);
            }
        });
    }

    private void populatePlants(SimulationPopulation population)
    {
        Random rand = Randomizer.getRandom();
        field.forEachLocation((row, col) -> {
            Location location = new Location(row, col);
            Plant plant = createPlantAt(rand, location);
            if(plant != null) {
                population.addPlant(plant);
            }
        });
    }

    private Animal createAnimalAt(Random rand, Location location)
    {
        for (AnimalSpecies species : ANIMAL_SPAWN_ORDER) {
            if(rand.nextDouble() <= species.getSpawnProbability()) {
                return animalFactory.create(species, location);
            }
        }
        return null;
    }

    private Plant createPlantAt(Random rand, Location location)
    {
        for (PlantSpecies species : PLANT_SPAWN_ORDER) {
            if(rand.nextDouble() <= species.getSpawnProbability()) {
                return plantFactory.create(species, location);
            }
        }
        return null;
    }
}

import java.util.Random;
/**
 * Responsible for mutating the weather of the simulation by randomly selecting a new weather(following a uniform distribution)
 * @version 1.0
 */
public class WeatherHandler
{

    /*///////////////////////////////////////////////////////////////
                                   STATE
    //////////////////////////////////////////////////////////////*/

    private Weather currentWeather;
    private int lastRecordedDay;
    private final Random rand = Randomizer.getRandom();
    private final SimulatorClock clock;

    /*///////////////////////////////////////////////////////////////
                                CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    /**
     * Creates a new Weather handler
     */
    public WeatherHandler(SimulatorClock clock)
    {
        this.clock = clock;
        reset();
    }

    /**
     * Accessor Method for the current weathet
     * @return the current weather
     */
    public Weather getWeather()
    {
        return currentWeather;
    }

    /**
     * Randomly selects a new weather everyday
     */
    public void updateWeather()
    {
        if(lastRecordedDay != clock.getDayCount()) {
            currentWeather = getRandomWeather();
            lastRecordedDay = clock.getDayCount();
        }
    }

    /**
     * Reset the tracked weather state for a new simulation run.
     */
    public void reset()
    {
        currentWeather = getRandomWeather();
        lastRecordedDay = clock.getDayCount();
    }

    /**
     *  Returns a random weather amongs the list of possible types of weather
     *  @return the randomly selected weather
     */
    private Weather getRandomWeather()
    {
        return Utils.getRandomEnumValue(Weather.class);
    }
}

/**
 * Plant factory for creating objects that extend the Plant class.
 *
 * @version 1.0
 */
public class PlantFactory
{

    /*///////////////////////////////////////////////////////////////
                                STATE
    //////////////////////////////////////////////////////////////*/

    private Field field;

    /*///////////////////////////////////////////////////////////////
                                CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    /**
     * Creates a Plant Factory.
     * 
     * @param field reference to field to later pass in to plants.
     */
    public PlantFactory(Field field)
    {
        this.field = field;
    }

    /**
     * Creates a Plant given an input plant type.
     * 
     * @param plantType the type of the plant.
     * @param location The base location of the newly created plant.
     * @return the created plant.
     */
    public Plant create(PlantSpecies plantType, Location location) {
        if(plantType == null) {
            return null;
        }
        return plantType.createRandom(field, location);
    }
}

/**
 * Factory for creating animals from explicit species definitions.
 *
 * @version 1.0
 */
public class AnimalFactory
{

    private final Field field;

    /*///////////////////////////////////////////////////////////////
                                CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    /**
     * Creates an AnimalFactory
     * @param reference to field to later pass in to animals
     */
    public AnimalFactory(Field field) 
    {
        this.field = field;
    }

    /**
     * Creates an animal of the given species.
     *
     * @param species the species to create.
     * @param location The base location of the newly created animal
     * @return the created animal
     */
    public Animal create(AnimalSpecies species, Location location)
    {
        if(species == null) {
            return null;
        }
        return species.createRandom(field, location);
    }
}

