/**
 * Tracks a homogeneous population of actors and applies per-step updates.
 */
public class ActorPopulation<T extends Actor>
{
    private final Class<T> actorType;
    private final List<T> actors;

    public ActorPopulation(Class<T> actorType)
    {
        this.actorType = actorType;
        this.actors = new ArrayList<>();
    }

    public void add(T actor)
    {
        actors.add(actor);
    }

    public void clear()
    {
        actors.clear();
    }

    public int size()
    {
        return actors.size();
    }

    public T get(int index)
    {
        return actors.get(index);
    }

    public void simulateStep(Weather weather, DayState dayState)
    {
        List<T> newborns = new ArrayList<>();
        ActorSink sink = actor -> appendNewActor(newborns, actor);
        for(Iterator<T> it = actors.iterator(); it.hasNext(); ) {
            T actor = it.next();
            actor.act(sink, weather, dayState);
            if(!actor.isAlive()) {
                it.remove();
            }
        }
        actors.addAll(newborns);
    }

    private void appendNewActor(List<T> newborns, Actor actor)
    {
        if(!actorType.isInstance(actor)) {
            throw new IllegalStateException(
                "Expected newborn actor of type " + actorType.getSimpleName()
                    + " but got " + actor.getClass().getSimpleName()
            );
        }
        newborns.add(actorType.cast(actor));
    }
}

/**
 * Owns the live animal and plant populations in the simulation.
 */
public class SimulationPopulation
{
    private final ActorPopulation<Animal> animals;
    private final ActorPopulation<Plant> plants;

    public SimulationPopulation()
    {
        animals = new ActorPopulation<>(Animal.class);
        plants = new ActorPopulation<>(Plant.class);
    }

    public void addAnimal(Animal animal)
    {
        animals.add(animal);
    }

    public void addPlant(Plant plant)
    {
        plants.add(plant);
    }

    public void clear()
    {
        animals.clear();
        plants.clear();
    }

    public void infectInitialAnimals(int count)
    {
        int infectedCount = Math.min(count, animals.size());
        for (int i = 0; i < infectedCount; i++) {
            animals.get(i).setInfectionTimestamp(0);
        }
    }

    public void simulateStep(Weather weather, DayState dayState)
    {
        plants.simulateStep(weather, dayState);
        animals.simulateStep(weather, dayState);
    }
}

import java.util.Random;
import java.util.List;
/**
 * A blueprint for how a typical plant behaves. A plant grows according to the weather 
 * conditions and daylight, and feeds more as it grows.
 *
 * @version 1.0
 */
public abstract class Plant implements Actor
{

    /*///////////////////////////////////////////////////////////////
                                  STATE
    //////////////////////////////////////////////////////////////*/

    private static final int FEEDING_FACTOR = 2;
    protected boolean alive;
    protected Location location;
    protected int age;
    protected int health;
    protected int feedingValue; 
    protected Field field;

    private static final Random rand = Randomizer.getRandom();

    /*///////////////////////////////////////////////////////////////
                                CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    /**
     * Creates a plant.
     * 
     * @param randomAge Boolean flag denoting whether or not to randomly generate an age for this plant
     * @param field The field currently occupied
     * @param location The location of the plant
     * @param maxAge The maximum age the plant can take
     */
    public Plant(boolean randomAge,Field field, Location location, int maxAge) 
    {
        if(randomAge) {
            this.age = rand.nextInt(maxAge);
            this.feedingValue = age * FEEDING_FACTOR;
        } else {
            this.age = 0;
            this.feedingValue = 0;
        }
        this.alive = true;
        this.field = field;
        setLocation(location);
    }

    /*///////////////////////////////////////////////////////////////
                            PLANT BEHAVIOUR LOGIC
    //////////////////////////////////////////////////////////////*/

    /**
     * Make this plant act - that is: make it do
     * whatever it wants/needs to do.
     * 
     * @param newPlants Receives newly generated plants.
     * @param weather The current weather
     * @param dayState The different state of the day
     */

    public final void act(ActorSink newPlants, Weather weather, DayState dayState)
    {
        if(!canAct(dayState)) {
            return;
        }
        grow(getMaxAge());
        if(!isAlive()) {
            return;
        }
        multiply(getSpreadProbability(weather), newPlants);
    }

    /**
     * Returns the species definition for this plant.
     *
     * @return the current plant species.
     */
    protected abstract PlantSpecies getSpecies();

    @Override
    public final ActorType getActorType()
    {
        return getSpecies();
    }

    protected abstract int getMaxAge();

    protected abstract double getSpreadProbability(Weather weather);

    protected boolean canAct(DayState dayState)
    {
        return dayState != DayState.NIGHT;
    }

    /**
     * Increments the age of the plant.
     * 
     * @param maxAge The maximum age a plant can take.
     */
    private void incrementAge(int maxAge) {
        age++;
        if(age > maxAge) {
            setDead();
        }
    }

    /**
     * Updates how much the plant will feed if it is to be eaten.
     */
    private void updateFeedingValue()
    {
        this.feedingValue = age * FEEDING_FACTOR;
    }

    /**
     * Updates the age and how much the plant will feed.
     * 
     * @param maxAge The maximum age a plant can take.
     */
    protected void grow(int maxAge)
    {
        incrementAge(maxAge);
        updateFeedingValue();
    }

    /**
     * Imitates the spread/growth of a plant.
     * 
     * @param spreadProbability likelihood a spreading to the next cell.
     * @param newPlants receives the newly generated plants.
     */
    protected void multiply(double spreadProbability, ActorSink newPlants)
    {
        List<Location> freeLocs = field.getFreeAdjacentTerrain(location);
        for ( Location loc : freeLocs) {
            if(rand.nextDouble() < spreadProbability) {
                Plant plant = getSpecies().createYoung(field, loc);
                newPlants.add(plant);
            }
        }
    }

    /*///////////////////////////////////////////////////////////////
                          ACCESSOR AND MUTATORS
    //////////////////////////////////////////////////////////////*/

    /**
     * Accessor method to denote whether or not the plant is alive.
     * 
     * @return flag conveying if the plant is alive.
     */
    public boolean isAlive()
    {
        return alive;
    }

    /**
     * Accessor method for the feeding value of the plant.
     * 
     * @return the feeding value of the plant.
     */
    public int getFeedingValue()
    {
        return feedingValue;
    }

    /**
     * Mutator method for the location of the plant.
     * 
     * @param newLocation the new location to be set.
     */
    protected void setLocation(Location newLocation)
    {
        if(location != null) {
            field.clearPlant(location);
        }
        location = newLocation;
        field.placePlant(this, newLocation);
    }

    /**
     * Sets the plant dead and removes all references to it, as well as its storage.
     */
    protected void setDead()
    {
        alive = false;
        if(location != null) {
            //errain.clear(location);
            field.clearPlant(location);
            location = null;
            field = null;
        }
    }
}

import java.util.List;
import java.util.Iterator;
import java.util.Random;
/**
 * A class representing shared characteristics of animals.
 *
 * @version 1.3
 */
public abstract class Animal implements Actor
{

    /*///////////////////////////////////////////////////////////////
                                  STATE
    //////////////////////////////////////////////////////////////*/

    private boolean alive;
    private Field field;
    private Location location;
    protected int age;
    protected final Gender gender;
    protected int foodLevel;
    protected Integer infectionTimestamp;

    private static final Random rand = Randomizer.getRandom();

    /*///////////////////////////////////////////////////////////////
                                CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    /**
     * Create a new animal at location in field.
     * 
     * @param randomAge flag indicating whether to randomly generate age and foodLevel or not
     * @param field The field currently occupied.
     * @param location The location within the field.
     * @param gender Gender of the animal
     * @param baseLevel base food level of an animal
     * @param maxAge maximum age the animal can take
     */
    public Animal(boolean randomAge, Field field, Location location, Gender gender,int baseLevel, int maxAge)
    {
        if (randomAge) {
            this.age = rand.nextInt(maxAge);
            this.foodLevel = rand.nextInt(baseLevel);
        } else {
            this.foodLevel = baseLevel;
            this.age = 0;
        }
        this.alive = true;
        this.field = field;
        this.gender = gender;
        this.infectionTimestamp = null;
        setLocation(location);
    }

    /*///////////////////////////////////////////////////////////////
                            ANIMAL BEHAVIOUR LOGIC
    //////////////////////////////////////////////////////////////*/

    /**
     * Increments the age of the animal.
     * 
     * @param maxAge The maximum age of the animal before he dies.
     */
    protected void incrementAge(int maxAge)
    {
        age++;
        if(age > maxAge) { 
            setDead();
        }
    }

    /**
     * Increment the hunger of the animal.
     */
    protected void incrementHunger()
    {
        foodLevel--;
        if(foodLevel <= 0) {
            setDead();  
        }
    }

    /**
     * Make this animal act - that is: make it do
     * whatever it wants/needs to do.
     * 
     * @param newAnimals Receives newly born animals.
     * @param weather The current weather
     * @param dayState The different state of the day
     */
    abstract public void act(ActorSink newAnimals, Weather weather, DayState dayState);

    /**
     * Returns the amount by which the hungerlevel would increment by if the animal were to be eaten.
     * 
     * @return the feeding value
     */
    abstract public int getFeedingValue();

    /**
     * Returns the species definition for this animal.
     *
     * @return the current animal species.
     */
    protected abstract AnimalSpecies getSpecies();

    @Override
    public final ActorType getActorType()
    {
        return getSpecies();
    }

    /**
     * Imitates the meeting of the animal by breeding new born animals.
     * 
     * @param newAnimals receives the animals to be born.
     * @param maxLitter the maximum amount animals that the animal can breed.
     * @param breedingProbability the likelyhood of giving birth.
     * @param breedingAge the minimum age to be able to breed.
     */
    protected void meet(ActorSink newAnimals,int maxLitter, double breedingProbability, int breedingAge)
    {
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Animal animal = field.getAnimalAt(where);
            if(animal == null || animal.getSpecies() != getSpecies()) {
                continue;
            }
            if(animal.getGender() == this.getGender()) {
                continue;
            }
            int births = breed(maxLitter, breedingProbability, breedingAge);
            giveBirth(newAnimals, births);
        }
    }

    /**
     * Returns the amount of animals to breed.
     * 
     * @param maxLitter the maximum amount of animals that the animal can breed.
     * @param breedingProbability indicates the likelyhood of breeding.
     * @param breedingAge The minimum age to be able to breed.
     * @return an integer representing the amount of animals to give birth.
     */
    private int breed(int maxLitter, double breedingProbability, int breedingAge)
    {
        int births = 0;
        if(age >= breedingAge){
            double randomValue = rand.nextDouble();
            if(randomValue <= breedingProbability) {
                births = rand.nextInt(maxLitter) + 1;
            }
        }
        return births;
    }

    /**
     * Gives birth to animal by appending the animals to the input list.
     * 
     * @param newAnimals receives the new born animals.
     * @param births number of animals to give birth.
     */
    private void giveBirth(ActorSink newAnimals, int births)
    {
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        for (int i = 0; i < births && free.size() > 0; i++) {
            Location loc = free.remove(0);
            Gender randomGender = Utils.getRandomEnumValue(Gender.class);
            Animal newBorn = getSpecies().createYoung(field, loc, randomGender);
            newAnimals.add(newBorn);
        }
    }

    /*///////////////////////////////////////////////////////////////
                          ACCESSOR AND MUTATORS
    //////////////////////////////////////////////////////////////*/

    /**
     * Accessor method for the gender of the animal.
     * 
     * @return the gender of the animal.
     */
    protected Gender getGender()
    {
        return this.gender;
    }

    /**
     * Accessor method for the timestamp of the infection.
     * 
     * @return the step at which the animal got infected.
     */
    public Integer getInfectionTimestamp()
    {
        return infectionTimestamp;
    }

    /**
     * Mutator method for the timestamp of the infection.
     * 
     * @param step The step at which the animal got infected.
     */
    public void setInfectionTimestamp(int step)
    {
        infectionTimestamp = step;
    }

    /**
     * Check whether the animal is alive or not.
     * 
     * @return true if the animal is still alive.
     */
    public boolean isAlive()
    {
        return alive;
    }

    /**
     * Indicate that the animal is no longer alive.
     * 
     * It is removed from the field.
     */
    protected void setDead()
    {
        alive = false;
        if(location != null) {
            field.clear(location);
            location = null;
            field = null;
        }
    }

    /**
     * Return the animal's location.
     * 
     * @return The animal's location.
     */
    protected Location getLocation()
    {
        return location;
    }

    /**
     * Place the animal at the new location in the given field.
     * 
     * @param newLocation The animal's new location.
     */
    protected void setLocation(Location newLocation)
    {
        if(location != null) {
            field.clear(location);
        }
        location = newLocation;
        field.placeAnimal(this, newLocation);
    }

