import java.util.Random;
/**
 * A class responsible for generating the population,
 * as well as setting up the colours associated with each actor type.
 *
 * @version 1.0
 */
public class PopulationGenerator
{

    /*///////////////////////////////////////////////////////////////
                                 CONSTANTS
    //////////////////////////////////////////////////////////////*/

    // A constant for initial number of infections in the generated population.
    private static final int INITIAL_INFECTION_COUNT = 11;
    private static final AnimalSpecies[] ANIMAL_SPAWN_ORDER = {
        AnimalSpecies.FOX,
        AnimalSpecies.REINDEER,
        AnimalSpecies.SHEEP,
        AnimalSpecies.BEAR,
        AnimalSpecies.WOLVERINE
    };
    private static final PlantSpecies[] PLANT_SPAWN_ORDER = {
        PlantSpecies.GRASS,
        PlantSpecies.SAGE,
        PlantSpecies.SEDGE
    };

    /*///////////////////////////////////////////////////////////////
                                   STATE
    //////////////////////////////////////////////////////////////*/

    private final SimulatorView view;
    private final AnimalFactory animalFactory;
    private final PlantFactory plantFactory;
    private final Field field;

    @FunctionalInterface
    private interface PopulationAdder<T extends Actor>
    {
        void add(SimulationPopulation population, T actor);
    }

    /*///////////////////////////////////////////////////////////////
                                CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    /**
     * Construct a population generator and set up the colours for representation of each animal class.
     */
    public PopulationGenerator(SimulatorView view, Field field)
    {
        this.view = view;
        this.field = field;
        animalFactory = new AnimalFactory(field);
        plantFactory = new PlantFactory(field);
        setUpColors();
    }

    /**
     * The RGB colours associated with the supported actor types.
     */
    private void setUpColors()
    {
        registerColors(AnimalSpecies.values());
        registerColors(PlantSpecies.values());
        view.showColors();
    }

    /**
     * Populate the grid with animals and plants, infect the animals.
     * 
     * @param population The population to populate.
     */
    public void populate(SimulationPopulation population)
    {
        field.clear();
        populateActors(population, ANIMAL_SPAWN_ORDER, animalFactory, SimulationPopulation::addAnimal);
        population.infectInitialAnimals(INITIAL_INFECTION_COUNT);
        populateActors(population, PLANT_SPAWN_ORDER, plantFactory, SimulationPopulation::addPlant);
    }

    private void registerColors(SpawnableActorType<?>[] actorTypes)
    {
        for (SpawnableActorType<?> actorType : actorTypes) {
            view.setColor(actorType, actorType.getColor());
        }
    }

    private <T extends Actor, S extends SpawnableActorType<T>> void populateActors(
        SimulationPopulation population,
        S[] spawnOrder,
        ActorFactory<T, S> factory,
        PopulationAdder<T> populationAdder
    ) {
        Random rand = Randomizer.getRandom();
        field.forEachLocation((row, col) -> {
            Location location = new Location(row, col);
            T actor = createActorAt(rand, location, spawnOrder, factory);
            if(actor != null) {
                populationAdder.add(population, actor);
            }
        });
    }

    private <T extends Actor, S extends SpawnableActorType<T>> T createActorAt(
        Random rand,
        Location location,
        S[] spawnOrder,
        ActorFactory<T, S> factory
    ) {
        for (S species : spawnOrder) {
            if(rand.nextDouble() <= species.getSpawnProbability()) {
                return factory.create(species, location);
            }
        }
        return null;
    }
}

import java.util.NavigableMap;
import java.util.TreeMap;
import java.util.List;
import java.util.ArrayList;
import java.util.Random;
/**
 * Class responsible for handling the simulation of the disease.
 *
 * @version 1.0
 */
public class DiseaseHandler
{

    /*///////////////////////////////////////////////////////////////
                                 CONSTANTS
    //////////////////////////////////////////////////////////////*/

    // cooldown before the animal achieves natural immunity
    private static final int DISINFECTION_DURATION = 5;
    private final Random rand = Randomizer.getRandom();
    private final Field field;

    /*///////////////////////////////////////////////////////////////
                                   STATE
    //////////////////////////////////////////////////////////////*/

    private final NavigableMap<Integer, Integer> infectionCounts;
    private int currentStep;

    /*///////////////////////////////////////////////////////////////
                                CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    /**
     * Creates a new disease handler
     * @param field The field to later get the animals per block and compute the density
     */
    public DiseaseHandler(Field field)
    {
        this.field = field;
        infectionCounts = new TreeMap<>();
        reset();
    }

    /*///////////////////////////////////////////////////////////////
                          DISEASE SIMULATION LOGIC
    //////////////////////////////////////////////////////////////*/

    /**
     * Simulates the disease by iterating through every block in the field, and computing the density of the number of ppl infected 
     * in the given block to determine the likelyhood of being infected in the block
     */
    public void simulateDiseaseStep()
    {
        currentStep++;
        InfectionTally infectionTally = new InfectionTally();
        field.forEachAnimalBlock(block -> {
            infectionTally.addInfected(evaluateBlock(block));
        });
        infectionCounts.put(currentStep, infectionTally.getInfectedCount());
    }

    private int evaluateBlock(List<Animal> block)
    {
        int infectedCount = countActiveInfections(block);
        infectSusceptibleAnimals(block, infectedCount);
        return infectedCount;
    }

    private int countActiveInfections(List<Animal> block)
    {
        int infectedCount = 0;
        for(Animal animal : block) {
            if(isActivelyInfected(animal)) {
                infectedCount++;
            }
        }
        return infectedCount;
    }

    private void infectSusceptibleAnimals(List<Animal> block, int infectedCount)
    {
        double infectionProbability = calculateInfectionProbability(block.size(), infectedCount);
        if(infectionProbability == 0.0) {
            return;
        }

        for(Animal animal : findSusceptibleAnimals(block)) {
            if(rand.nextDouble() < infectionProbability) {
                animal.setInfectionTimestamp(currentStep);
            }
        }
    }

    private List<Animal> findSusceptibleAnimals(List<Animal> block)
    {
        List<Animal> susceptibleAnimals = new ArrayList<>();
        for(Animal animal : block) {
            if(animal.getInfectionTimestamp() == null) {
                susceptibleAnimals.add(animal);
            }
        }
        return susceptibleAnimals;
    }

    private boolean isActivelyInfected(Animal animal)
    {
        Integer infectionTimestamp = animal.getInfectionTimestamp();
        return infectionTimestamp != null
            && currentStep - infectionTimestamp < DISINFECTION_DURATION;
    }

    private double calculateInfectionProbability(int blockSize, int infectedCount)
    {
        if(blockSize == 0) {
            return 0.0;
        }
        return (double) infectedCount / (double) blockSize;
    }

    /**
     * Reset the disease state for a fresh simulation run.
     */
    public void reset()
    {
        currentStep = 0;
        infectionCounts.clear();
    }

    /**
     * Returns the tracked infection counts over time.
     */
    public NavigableMap<Integer, Integer> getInfectionCounts()
    {
        return infectionCounts;
    }

    private static class InfectionTally
    {
        private int infectedCount;

        void addInfected(int amount)
        {
            infectedCount += amount;
        }

        int getInfectedCount()
        {
            return infectedCount;
        }
    }
}
